import{_ as t,o as a,c as n,ai as o}from"./chunks/framework.jD4ETUAz.js";const u=JSON.parse(`{"title":"FAQ","description":"Answers about cninfo-mcp, the open-source CNINFO MCP server: official status, cost, supported clients, markets, English filings, data accuracy and rate limits.","frontmatter":{"title":"FAQ","description":"Answers about cninfo-mcp, the open-source CNINFO MCP server: official status, cost, supported clients, markets, English filings, data accuracy and rate limits.","faq":true,"editLink":false,"translation":"faq.md","head":[["link",{"rel":"canonical","href":"https://youhaozhao.github.io/cninfo-mcp/en/faq"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"cninfo-mcp"}],["meta",{"property":"og:title","content":"FAQ | cninfo-mcp"}],["meta",{"property":"og:description","content":"Answers about cninfo-mcp, the open-source CNINFO MCP server: official status, cost, supported clients, markets, English filings, data accuracy and rate limits."}],["meta",{"property":"og:url","content":"https://youhaozhao.github.io/cninfo-mcp/en/faq"}],["meta",{"property":"og:image","content":"https://youhaozhao.github.io/cninfo-mcp/og-en.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"FAQ | cninfo-mcp"}],["meta",{"name":"twitter:description","content":"Answers about cninfo-mcp, the open-source CNINFO MCP server: official status, cost, supported clients, markets, English filings, data accuracy and rate limits."}],["meta",{"name":"twitter:image","content":"https://youhaozhao.github.io/cninfo-mcp/og-en.png"}],["link",{"rel":"alternate","hreflang":"zh","href":"https://youhaozhao.github.io/cninfo-mcp/faq"}],["link",{"rel":"alternate","hreflang":"en","href":"https://youhaozhao.github.io/cninfo-mcp/en/faq"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://youhaozhao.github.io/cninfo-mcp/en/faq"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"FAQ\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/faq\\"}]},{\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"What is cninfo-mcp?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"cninfo-mcp is an open-source Model Context Protocol (MCP) server. Once connected, an AI assistant such as Claude can search company announcements, read annual reports and prospectuses, fetch financial and shareholder data, and download PDFs from CNINFO. It is built for research on China A-shares and provides eight tools, listed in the tools reference.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"What is CNINFO?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"CNINFO (巨潮资讯网, cninfo.com.cn) is the disclosure website for listed companies designated by the China Securities Regulatory Commission, operated by Shenzhen Securities Information Co., Ltd. Announcements and periodic reports of companies listed in Shanghai, Shenzhen and Beijing are published there.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Is cninfo-mcp an official CNINFO product?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"No. It is a community-maintained open-source project with no affiliation, partnership or licence from Shenzhen Securities Information Co., Ltd. It calls the query endpoints that the CNINFO website itself uses, not an official data service, so those endpoints can change, be rate-limited or be withdrawn at any time.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Is it free? What is the licence?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes, it is free. The project is MIT-licensed and the source is on GitHub.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"What do I need to run it?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Node.js 22.13 or newer. The published package is self-contained and pulls in no other packages at install time. See Install and configure.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Do I need an API key, an account or Python?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"No. The server does not need, and never reads, accounts, cookies or secrets. Since version 3.0 it no longer depends on Python.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Which AI clients does it work with?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Any client that supports MCP over stdio, including Claude Code, Claude Desktop, Cursor, VS Code, Codex CLI, Gemini CLI, OpenClaw, Cline, Windsurf and Cherry Studio.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Does it work on Windows?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes. Windows, macOS and Linux are supported, and the project's continuous integration installs the published package and runs the offline self-test on all three.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Does it work outside mainland China?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes, as long as your network can reach cninfo.com.cn. Run npx -y @youhaozhao/cninfo-mcp probe to check.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Which markets are covered?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Announcement search covers companies listed in Shanghai, Shenzhen and Beijing (including B shares) and Hong Kong announcements; funds and bonds can be searched by code. Report listings, financial data and company data cover Shanghai, Shenzhen and Beijing listings, including the main boards, ChiNext and the STAR Market.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Are the filings available in English?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Almost all filings on CNINFO are in Chinese. Your assistant reads the Chinese text and can answer in English with page references. Where a company also files an English version of a report, listreports returns it when includevariants is set.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Do I have to write prompts in Chinese?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"No. Ask in English and identify companies by stock code, such as 600519 or 000001.SZ. The tools also accept Chinese short names (贵州茅台), and assistants usually resolve well-known English company names to the right code on their own.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Does it provide stock prices or price history?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"No. cninfo-mcp focuses on disclosures and fundamentals. For quotes and technical indicators, pair it with an MCP server built on a market-data source.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Can it search the full text of all announcements?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"No. Announcements are searched by title keyword. Inside a single document, readdocument can locate keywords with its query argument.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"How many periods of financial data are available?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"getfinancials returns key ratios, the income statement, the balance sheet and the cash flow statement for up to the five most recent periods of one period type, which is what the upstream source offers. Statement amounts are in units of 10,000 CNY (万元). Quarterly and semi-annual figures are cumulative year-to-date.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"How accurate is the data?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Announcements and reports are the documents the listed companies filed. The structured data is the condensed view shown on CNINFO's company pages and can differ in definition from the full statements, so check important figures against the filing itself. The tool makes no guarantee of accuracy, completeness or timeliness.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Do I need to download a report to read it?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"No. readdocument reads the PDF text directly. The download tools are only for keeping a local copy. See Read Chinese annual reports with AI.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Can I download annual reports in bulk?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes. Ask the assistant to download a company's annual reports without naming a year and downloadreports saves every year available. Keep the default concurrency and do not use the tool for high-frequency or large-scale scraping. See Download Chinese annual reports.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Why do I get HTTP 403?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"CNINFO uses 403 to signal rate limiting: too many requests in a short time are answered with 403 and a temporary IP block. The server rate-limits all upstream requests and pauses globally before retrying, so it usually recovers by itself.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"What does complete: false mean in a result?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"The result is partial: some pages, datasets or files failed. What was retrieved is still returned, with warnings or errors describing what is missing. Retrying later usually fills the gap.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Is it compliant to retrieve data this way?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"The project does not host or relay any report content: your own machine fetches everything directly from CNINFO. The website's footer states that its content is copyrighted by Shenzhen Securities Information Co., Ltd., and the reports themselves are disclosed by the listed companies. How you use downloaded files, especially redistribution and commercial use, is for you to verify.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Which hosts does it contact and which files does it write?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"It only contacts https://www.cninfo.com.cn (queries and data) and https://static.cninfo.com.cn (documents). Only the two download tools write user-visible files, and only inside the download root; apart from that the server writes to its own cache folder.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Is the output investment advice?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"No. The tool retrieves and organises public disclosures. It is not investment advice.\\"}}]}]}"]]},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md","lastUpdated":1794815217000}`),i={name:"en/faq.md"};function s(r,e,c,d,h,l){return a(),n("div",null,[...e[0]||(e[0]=[o("",52)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
